public sealed class AtomicMutationPlanExecutor{readonly FileExecutionJournal journal;readonly IDocumentRevalidator revalidator;public AtomicMutationPlanExecutor(FileExecutionJournal journal,IDocumentRevalidator revalidator){this.journal=journal;this.revalidator=revalidator;}
 public PlanExecutionResult Execute(string source,string output,MutationPlan plan,string requestId,string idempotencyKey){DocumentIdentity input;try{input=DocumentIdentityService.FromFile(source);}catch(Exception e){return F(PlanExecutionOutcome.WRITE_FAILED,e.Message,"",new("SHA-256",new string('0',64)));}if(input.Digest!=plan.InputDocumentDigest)return F(PlanExecutionOutcome.STALE_DOCUMENT,"Input identity differs from plan.","",input);if(plan.HasConflict)return F(PlanExecutionOutcome.PLAN_CONFLICT,"Conflicting operations.","",input);var safety=PackageSafetyPreflight.Inspect(source);if(!safety.IsReadable||safety.PatchPolicy!=PatchPolicy.NORMAL||safety.IsSigned||safety.IsProtected||safety.UnsupportedFeatures.Count>0)return F(PlanExecutionOutcome.PACKAGE_NOT_MUTABLE,"Package safety blocks mutation.","",input);var src=Path.GetFullPath(source);var dst=Path.GetFullPath(output);if(StringComparer.OrdinalIgnoreCase.Equals(src,dst))return F(PlanExecutionOutcome.OUTPUT_PATH_INVALID,"New output only.","",input);if(File.Exists(dst))return F(PlanExecutionOutcome.OUTPUT_ALREADY_EXISTS,"Output exists.","",input);JournalBeginResult begin;try{begin=journal.Begin(idempotencyKey,plan,requestId,input.Digest);}catch(JournalException e){return F(PlanExecutionOutcome.JOURNAL_FAILURE,e.Message,"",input);}if(begin.Decision==JournalDecision.IDEMPOTENCY_CONFLICT)return F(PlanExecutionOutcome.IDEMPOTENCY_CONFLICT,"Idempotency key conflict.",begin.Record?.ExecutionId??"",input);if(begin.Decision is JournalDecision.ALREADY_EXECUTED or JournalDecision.PREVIOUS_FAILED){var r=begin.Record!;return new(begin.Decision==JournalDecision.ALREADY_EXECUTED?PlanExecutionOutcome.ALREADY_EXECUTED:PlanExecutionOutcome.WRITE_FAILED,r.Status==ExecutionStatus.SUCCEEDED,r.ExecutionId,r.OutputReference,input,r.OutputDigest is null?null:new("SHA-256",r.OutputDigest),null,begin.Decision.ToString());}var eid=begin.Record!.ExecutionId;string? tmp=null;try{var dir=Path.GetDirectoryName(dst)!;Directory.CreateDirectory(dir);tmp=Path.Combine(dir,$".{Path.GetFileName(dst)}.{Guid.NewGuid():N}.tmp");PackagePreserver.CopyWithoutMutation(source,tmp);if(DocumentIdentityService.FromFile(tmp).Digest!=input.Digest)throw new IntegrityException("Input snapshot changed after preflight.");using(var d=WordprocessingDocument.Open(tmp,true)){foreach(var authorized in plan.Operations)Apply(d,authorized.Value);d.MainDocumentPart!.Document.Save();}using(var d=WordprocessingDocument.Open(tmp,false)){foreach(var authorized in plan.Operations)Verify(d,authorized.Value);}var afterSafety=PackageSafetyPreflight.Inspect(tmp);if(!afterSafety.IsReadable||afterSafety.PatchPolicy!=PatchPolicy.NORMAL)throw new IntegrityException("Package preflight failed after write.");if(!PackagePreserver.PartInventory(source).SequenceEqual(PackagePreserver.PartInventory(tmp)))throw new IntegrityException("Part inventory changed.");if(DocumentIdentityService.FromFile(source).Digest!=input.Digest)throw new InvalidOperationException("Source immutability violated.");var rv=revalidator.Revalidate(tmp);if(!rv.Completed||rv.RegressionFindings.Count>0){journal.Fail(eid,"REVALIDATION_FAILED");Del(tmp);tmp=null;return new(PlanExecutionOutcome.REVALIDATION_FAILED,false,eid,null,input,null,rv,"Full revalidation did not pass publication contract.");}var oid=DocumentIdentityService.FromFile(tmp);File.Move(tmp,dst,false);tmp=null;journal.Succeed(eid,oid.Digest,dst);return new(PlanExecutionOutcome.SUCCESS,true,eid,dst,input,oid,rv,"Atomic plan verified and published.");}catch(PreconditionException e){journal.Fail(eid,"PRECONDITION_FAILED");Del(tmp);tmp=null;return F(PlanExecutionOutcome.PRECONDITION_FAILED,e.Message,eid,input);}catch(TargetException e){journal.Fail(eid,e.Outcome.ToString());Del(tmp);tmp=null;return F(e.Outcome,e.Message,eid,input);}catch(IntegrityException e){journal.Fail(eid,"OUTPUT_INTEGRITY_FAILED");Del(tmp);tmp=null;return F(PlanExecutionOutcome.OUTPUT_INTEGRITY_FAILED,e.Message,eid,input);}catch(Exception){journal.Fail(eid,"WRITE_FAILED");Del(tmp);tmp=null;return F(PlanExecutionOutcome.WRITE_FAILED,"DOCX processing failed safely.",eid,input);}finally{Del(tmp);}}
 static void Apply(WordprocessingDocument d,PlanOperation op){var p=Resolve(d,op);if(op.Provenance!="DIRECT")throw new TargetException(PlanExecutionOutcome.PROVENANCE_UNSUPPORTED,"Direct formatting only.");if(op.Property=="paragraph.alignment"){var j=p.ParagraphProperties?.GetFirstChild<W.Justification>()??throw new TargetException(PlanExecutionOutcome.PROVENANCE_UNSUPPORTED,"Direct alignment missing.");var b=Align(j.Val?.Value);if(b!=op.ExpectedBefore)throw new PreconditionException($"Expected {op.ExpectedBefore}, actual {b}.");j.Val=op.DesiredAfter switch{"LEFT"=>W.JustificationValues.Left,"CENTER"=>W.JustificationValues.Center,"RIGHT"=>W.JustificationValues.Right,"JUSTIFY"=>W.JustificationValues.Both,_=>throw new TargetException(PlanExecutionOutcome.UNSUPPORTED_OPERATION,"Unsupported alignment.")};return;}if(op.Property=="paragraph.spacing.after"){var s=p.ParagraphProperties?.GetFirstChild<W.SpacingBetweenLines>()??throw new TargetException(PlanExecutionOutcome.PROVENANCE_UNSUPPORTED,"Direct spacing missing.");var b=s.After?.Value;if(b!=op.ExpectedBefore)throw new PreconditionException($"Expected {op.ExpectedBefore}, actual {b}.");if(!int.TryParse(op.DesiredAfter,out var v)||v<0||v>31680)throw new TargetException(PlanExecutionOutcome.UNSUPPORTED_OPERATION,"Unsupported spacing.");s.After=op.DesiredAfter;return;}throw new TargetException(PlanExecutionOutcome.UNSUPPORTED_OPERATION,"Unsupported property.");}
