 static string? Align(W.JustificationValues? v){if(v==W.JustificationValues.Left)return"LEFT";if(v==W.JustificationValues.Center)return"CENTER";if(v==W.JustificationValues.Right)return"RIGHT";if(v==W.JustificationValues.Both)return"JUSTIFY";return null;}static void Del(string? p){try{if(p is not null&&File.Exists(p))File.Delete(p);}catch{}}PlanExecutionResult F(PlanExecutionOutcome o,string reason,string id,DocumentIdentity input)=>new(o,false,id,null,input,null,null,reason);sealed class PreconditionException(string m):Exception(m);sealed class IntegrityException(string m):Exception(m);sealed class TargetException(PlanExecutionOutcome o,string m):Exception(m){public PlanExecutionOutcome Outcome{get;}=o;}}
